/**
 * Renders app/public/og-image.png (1200×630, seo-geo §3): the meeple logo from favicon.svg and the
 * app name and tagline on the accent colour. Run `pnpm og-image` after the name, tagline, accent or
 * logo change, and commit the PNG (it is not regenerated by the build). Uses the Playwright Chromium
 * the e2e tests already install — no extra dependency.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "@playwright/test";
import { app } from "../app.config.ts";
import { OG_IMAGE, escapeHtml } from "./seo.ts";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const logo = readFileSync(join(root, "app", "public", "favicon.svg"), "utf8");

// Layout values of a one-off image, not UI: the system font stack matches the app.
const html = `<!DOCTYPE html><html><body style="margin:0">
<div style="width:${String(OG_IMAGE.width)}px;height:${String(OG_IMAGE.height)}px;box-sizing:border-box;padding:96px;display:flex;align-items:center;gap:64px;background:${app.accent};font-family:-apple-system,BlinkMacSystemFont,'Inter','Segoe UI',system-ui,sans-serif;color:#FFFFFF">
  <div style="width:280px;height:280px;flex:none">${logo.replace("<svg ", '<svg width="280" height="280" ')}</div>
  <div>
    <div style="font-size:96px;font-weight:700;line-height:1.05">${escapeHtml(app.name)}</div>
    <div style="margin-top:24px;font-size:40px;line-height:1.25;opacity:0.9;text-wrap:balance">${escapeHtml(app.tagline)}</div>
  </div>
</div></body></html>`;

const browser = await chromium.launch();
try {
  const page = await browser.newPage({ viewport: { width: OG_IMAGE.width, height: OG_IMAGE.height }, deviceScaleFactor: 1 });
  await page.setContent(html);
  const file = join(root, "app", "public", OG_IMAGE.file);
  await page.screenshot({ path: file, type: "png" });
  console.log(`og-image: wrote ${file}`);
} finally {
  await browser.close();
}
